package com.example.puller.service;import com.example.puller.entity.OutboxEvent;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.util.*;import java.util.concurrent.TimeUnit;
@Service public class OrderPullerService{private final OutboxClaimService claims;private final KafkaTemplate<String,String> kafka;private final String topic;public OrderPullerService(OutboxClaimService c,KafkaTemplate<String,String> k,@Value("${order.poller.topic.name}")String t){claims=c;kafka=k;topic=t;}@Scheduled(fixedDelayString="${order.poller.fixed-delay-ms:2000}")public void poll(){List<OutboxEvent> list=claims.claim();for(OutboxEvent e:list){try{kafka.send(topic,e.getAggregateId(),e.getPayload()).get(10,TimeUnit.SECONDS);claims.published(e.getId());}catch(Exception ex){claims.failed(e.getId());}}}@Scheduled(fixedDelay=60000)public void recover(){claims.recoverStale();}}
